// Generated by crates/xtask from the Rust question model.
// Do not edit by hand; run ./build.sh (or cargo run -p xtask -- tsgen).

/**
 * How close a numeric response must be to count as correct.
 *
 * The tolerance is shared content because the browser shows it to the student
 * ("within 1%") and validates the entry format against it. The correct value
 * stays server-side.
 */
export type NumericTolerance =
  | { kind: "exact" }
  | {
      kind: "absolute";
      epsilon: number;
    }
  | {
      kind: "relative";
      fraction: number;
    }
  | {
      kind: "significantFigures";
      digits: number;
    };
